const root=document.documentElement,button=document.querySelector('.menu'),nav=document.querySelector('#navigation'),backdrop=document.querySelector('.nav-backdrop'),header=document.querySelector('.header');
const mobile=matchMedia('(max-width:760px)'),reduced=matchMedia('(prefers-reduced-motion:reduce)');
let menuOpen=false,savedScroll=0,closeTimer;
function setMenu(open,restoreFocus=true){
 open=open&&mobile.matches;if(open===menuOpen)return;menuOpen=open;clearTimeout(closeTimer);if(open)savedScroll=scrollY;
 button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open);header.classList.toggle('menu-open',open);
 document.querySelector('main').inert=open;document.querySelector('footer').inert=open;document.querySelector('.brand').inert=open;
 if(open){document.body.style.top=`-${savedScroll}px`;document.body.classList.add('nav-locked');backdrop.hidden=false;nav.inert=false;requestAnimationFrame(()=>header.classList.add('nav-visible'));button.focus({preventScroll:true});}
 else{header.classList.remove('nav-visible');nav.inert=mobile.matches;document.body.classList.remove('nav-locked');document.body.style.top='';const old=root.style.scrollBehavior;root.style.scrollBehavior='auto';window.scrollTo(0,savedScroll);root.style.scrollBehavior=old;closeTimer=setTimeout(()=>{backdrop.hidden=true},reduced.matches?0:280);if(restoreFocus)button.focus({preventScroll:true});}
}
button.addEventListener('click',()=>setMenu(!menuOpen));backdrop.addEventListener('click',()=>setMenu(false));
nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{setMenu(false,false);const url=new URL(link.href);if(url.pathname===location.pathname&&url.hash){const target=document.querySelector(url.hash);if(target){target.tabIndex=-1;target.focus({preventScroll:true});}}}));
 document.addEventListener('keydown',event=>{if(!menuOpen)return;if(event.key==='Escape'){event.preventDefault();setMenu(false);}if(event.key==='Tab'){const stops=[button,...nav.querySelectorAll('a')],first=stops[0],last=stops.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
mobile.addEventListener('change',()=>{setMenu(false);nav.inert=mobile.matches;});addEventListener('pagehide',()=>setMenu(false,false));root.classList.add('js');nav.inert=mobile.matches;
// Reveal meaningful groups once, keeping already visible content available.
let revealObserver;const groups=document.querySelectorAll('.section-head,.split>figure,.split>div,.service,.project-card,.why-grid article,.client-card,.detail-layout>div,.facts');
function setupReveals(){revealObserver?.disconnect();if(reduced.matches||!('IntersectionObserver'in window)){groups.forEach(el=>el.classList.remove('reveal'));return;}revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('revealed');revealObserver.unobserve(entry.target);}}),{threshold:.08,rootMargin:'0px 0px -20px 0px'});groups.forEach(el=>{if(el.getBoundingClientRect().top<innerHeight||el.classList.contains('revealed'))return;el.classList.add('reveal');el.style.setProperty('--reveal-delay',`${mobile.matches?0:([...el.parentElement.children].indexOf(el)%3)*70}ms`);revealObserver.observe(el);});}
setupReveals();
const timeline=document.querySelector('.steps'),steps=timeline?[...timeline.children]:[],hero=document.querySelector('.hero-photo');let ticking=false;
function updateScroll(){ticking=false;header.classList.toggle('scrolled',(menuOpen?savedScroll:scrollY)>24);if(timeline){const rect=timeline.getBoundingClientRect();if(rect.bottom>0&&rect.top<innerHeight){const progress=Math.max(0,Math.min(1,(innerHeight*.72-rect.top-26)/Math.max(1,rect.height-80)));timeline.style.setProperty('--progress',reduced.matches?1:(innerWidth<=1100?progress:(rect.top<innerHeight*.8?1:0)));steps.forEach((step,i)=>{if(reduced.matches||step.getBoundingClientRect().top<innerHeight*.76){step.style.setProperty('--step-delay',mobile.matches?'0ms':`${i*85}ms`);step.classList.add('active');}});}}if(hero)hero.style.setProperty('--parallax',`${!mobile.matches&&!reduced.matches?Math.min(12,scrollY*.025):0}px`);}
function scheduleScroll(){if(!ticking){ticking=true;requestAnimationFrame(updateScroll);}}
addEventListener('scroll',scheduleScroll,{passive:true});addEventListener('resize',scheduleScroll,{passive:true});reduced.addEventListener('change',()=>{setupReveals();updateScroll();});updateScroll();
const sectionLinks=[...nav.querySelectorAll('.nav-link')];if('IntersectionObserver'in window&&document.querySelector('#services')){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting)sectionLinks.forEach(link=>{const active=new URL(link.href).hash===`#${entry.target.id}`;link.classList.toggle('is-current',active);if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');});}),{rootMargin:'-15% 0px -55% 0px',threshold:0});document.querySelectorAll('section[id]').forEach(s=>observer.observe(s));}


